/* CompassJournal.module.css — Vitrina theme inspired by Tooplate Compass */

.root {
  /* Spine color roles */
  --vt-surface: #F7F9FC;
  --vt-surface-2: #FFFFFF;
  --vt-surface-deep: #0F172A;
  --vt-ink: #0F172A;
  --vt-ink-soft: #5A6B80;
  --vt-on-deep: #FFFFFF;
  --vt-accent: #0047AB;
  --vt-on-accent: #FFFFFF;
  --vt-accent-ink: #0047AB;
  --vt-accent-on-deep: #7AA7E8;
  --vt-line: #E2E8F0;

  /* Spacing */
  --space-xs: clamp(0.5rem, 1vw, 1rem);
  --space-sm: clamp(1rem, 2vw, 2rem);
  --space-md: clamp(2rem, 5vw, 5rem);
  --space-lg: clamp(4rem, 10vh, 10rem);
  --space-xl: clamp(6rem, 15vh, 15rem);
  --gutter: clamp(1.5rem, 4vw, 4rem);
  --max-w: 1400px;

  font-family: 'Inter', system-ui, sans-serif;
  line-height: 1.7;
  color: var(--vt-ink);
  background-color: var(--vt-surface);
}

.root *,
.root *::before,
.root *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

.root img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.root a {
  color: var(--vt-accent);
  text-decoration: none;
  transition: opacity 0.3s ease;
}

.root a:hover {
  opacity: 0.7;
}

.root a:focus-visible {
  outline: 2px solid var(--vt-accent);
  outline-offset: 2px;
}

/* Navigation */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1.5rem var(--gutter);
  background: color-mix(in srgb, var(--vt-surface-deep) 70%, transparent);
  backdrop-filter: blur(16px) saturate(1.4);
  -webkit-backdrop-filter: blur(16px) saturate(1.4);
  border-bottom: 1px solid color-mix(in srgb, var(--vt-on-deep) 6%, transparent);
  transition: background 0.5s ease, padding 0.4s ease;
}

.navIn {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  max-width: var(--max-w);
  margin: 0 auto;
}

.logo {
  font-family: 'Playfair Display', Georgia, serif;
  font-size: 1.125rem;
  font-weight: 600;
  letter-spacing: -0.02em;
  color: var(--vt-on-deep);
  text-transform: uppercase;
  text-decoration: none;
}

.brand {
  display: block;
  color: inherit;
}

.navLinks {
  display: flex;
  gap: 2rem;
  list-style: none;
}

.navLinks a {
  font-family: 'Inter', system-ui, sans-serif;
  font-size: 0.75rem;
  font-weight: 500;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: color-mix(in srgb, var(--vt-on-deep) 65%, transparent);
  text-decoration: none;
  transition: color 0.3s ease, letter-spacing 0.3s ease;
}

.navLinks a:hover {
  color: var(--vt-on-deep);
  letter-spacing: 0.14em;
  opacity: 1;
}

/* Hero */
.hero {
  position: relative;
  height: 100vh;
  width: 100%;
  overflow: hidden;
}

.heroImage {
  position: absolute;
  inset: 0;
}

.heroImage::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(
    0deg,
    color-mix(in srgb, var(--vt-surface-deep) 65%, transparent) 0%,
    color-mix(in srgb, var(--vt-surface-deep) 15%, transparent) 40%,
    color-mix(in srgb, var(--vt-surface-deep) 5%, transparent) 100%
  );
}

.heroContent {
  position: absolute;
  bottom: clamp(3rem, 8vh, 8rem);
  left: var(--gutter);
  right: var(--gutter);
  color: var(--vt-on-deep);
}

.heroIssue {
  font-family: 'Inter', system-ui, sans-serif;
  font-size: 0.7rem;
  font-weight: 500;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  margin-bottom: 1.5rem;
  opacity: 0.8;
}

.heroTitle {
  font-family: 'Playfair Display', Georgia, serif;
  font-size: clamp(3rem, 8vw, 7.5rem);
  font-weight: 400;
  line-height: 0.95;
  letter-spacing: -0.03em;
  max-width: 14ch;
  margin-bottom: 2rem;
}

.heroTitle em {
  font-style: italic;
  font-weight: 400;
}

.heroMeta {
  display: flex;
  align-items: center;
  gap: 2rem;
  font-family: 'Inter', system-ui, sans-serif;
  font-size: 0.8rem;
  font-weight: 400;
  letter-spacing: 0.04em;
  opacity: 0.7;
}

.heroMeta span {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.divider {
  width: 40px;
  height: 1px;
  background: var(--vt-on-deep);
  opacity: 0.4;
}

.heroScroll {
  position: absolute;
  bottom: clamp(3rem, 8vh, 8rem);
  right: var(--gutter);
  writing-mode: vertical-rl;
  font-family: 'Inter', system-ui, sans-serif;
  font-size: 0.65rem;
  font-weight: 500;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--vt-on-deep);
  opacity: 0.6;
  display: flex;
  align-items: center;
  gap: 1rem;
}

.heroScroll::before {
  content: '';
  width: 1px;
  height: 60px;
  background: var(--vt-on-deep);
  opacity: 0.4;
  animation: scrollPulse 2s ease-in-out infinite;
}

@keyframes scrollPulse {
  0%, 100% { opacity: 0.2; transform: scaleY(1); }
  50% { opacity: 0.6; transform: scaleY(1); }
}

/* Prologue */
.prologue {
  padding: var(--space-xl) var(--gutter);
  background: var(--vt-surface-2);
}

.prologueInner {
  max-width: 60ch;
  margin: 0 auto;
}

.prologueLabel {
  font-family: 'Inter', system-ui, sans-serif;
  font-size: 0.7rem;
  font-weight: 500;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--vt-accent);
  margin-bottom: var(--space-md);
  display: flex;
  align-items: center;
  gap: 1rem;
}

.prologueLabel::after {
  content: '';
  flex: 1;
  max-width: 120px;
  height: 1px;
  background: var(--vt-accent);
  opacity: 0.3;
}

.prologueText {
  font-family: 'Playfair Display', Georgia, serif;
  font-size: clamp(1.25rem, 2.5vw, 1.625rem);
  line-height: 1.75;
  color: var(--vt-ink);
  letter-spacing: -0.01em;
}

.prologueText::first-letter {
  font-family: 'Playfair Display', Georgia, serif;
  font-weight: 700;
  float: left;
  font-size: 5.5em;
  line-height: 0.8;
  margin-right: 0.08em;
  margin-top: 0.05em;
  color: var(--vt-accent);
}

.prologueText + .prologueText {
  margin-top: 1.5em;
  text-indent: 0;
}

.prologueText + .prologueText::first-letter {
  font-size: inherit;
  float: none;
  margin: 0;
  color: inherit;
  font-weight: inherit;
  line-height: inherit;
}

/* Route (Chapters with sticky image) */
.route {
  position: relative;
  background: var(--vt-surface);
}

.routeBg {
  position: sticky;
  top: 0;
  height: 100vh;
  width: 100%;
  overflow: hidden;
  z-index: 0;
}

.routeBg img {
  object-fit: cover;
}

.routeBg::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(
    90deg,
    var(--vt-surface) 0%,
    var(--vt-surface) 15%,
    color-mix(in srgb, var(--vt-surface) 85%, transparent) 30%,
    color-mix(in srgb, var(--vt-surface) 45%, transparent) 50%,
    color-mix(in srgb, var(--vt-surface) 10%, transparent) 75%,
    transparent 100%
  );
  z-index: 1;
  pointer-events: none;
}

.routeChapters {
  position: relative;
  z-index: 2;
  margin-top: -100vh;
  padding: var(--space-xl) var(--gutter);
}

.chapter {
  padding: 10vh 0;
  min-height: 80vh;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.chapter:first-child {
  padding-top: 5vh;
}

.chapterNumber {
  font-family: 'Playfair Display', Georgia, serif;
  font-size: clamp(4rem, 8vw, 6rem);
  font-weight: 400;
  color: var(--vt-accent);
  opacity: 0.12;
  line-height: 1;
  margin-bottom: 1rem;
}

.chapterLocation {
  font-family: 'Inter', system-ui, sans-serif;
  font-size: 0.7rem;
  font-weight: 500;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--vt-accent);
  margin-bottom: 1rem;
}

.chapterTitle {
  font-family: 'Playfair Display', Georgia, serif;
  font-size: clamp(2rem, 4vw, 3.25rem);
  font-weight: 400;
  line-height: 1.15;
  letter-spacing: -0.02em;
  color: var(--vt-ink);
  margin-bottom: 1.5rem;
  max-width: 18ch;
}

.chapterBody {
  font-family: 'Inter', system-ui, sans-serif;
  font-size: 0.95rem;
  line-height: 1.8;
  color: var(--vt-ink-soft);
  max-width: 48ch;
}

.chapterBody + .chapterBody {
  margin-top: 1em;
}

.chapterLink {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  margin-top: 2rem;
  font-family: 'Inter', system-ui, sans-serif;
  font-size: 0.8rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--vt-accent);
}

.chapterLink svg {
  width: 16px;
  height: 16px;
  transition: transform 0.3s ease;
}

.chapterLink:hover {
  opacity: 1;
}

.chapterLink:hover svg {
  transform: translateX(4px);
}

/* Gallery (Masonry) */
.gallery {
  padding: var(--space-xl) var(--gutter);
  background: var(--vt-surface-2);
}

.galleryHeader {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  margin-bottom: var(--space-md);
  padding-bottom: var(--space-sm);
  border-bottom: 1px solid var(--vt-line);
}

.galleryTitle {
  font-family: 'Playfair Display', Georgia, serif;
  font-size: clamp(2.5rem, 5vw, 4rem);
  font-weight: 400;
  line-height: 1.1;
  letter-spacing: -0.03em;
}

.galleryCount {
  font-family: 'Inter', system-ui, sans-serif;
  font-size: 0.75rem;
  font-weight: 500;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--vt-ink-soft);
  padding-bottom: 0.5rem;
}

.galleryGrid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  grid-auto-rows: clamp(180px, 20vw, 280px);
  gap: 6px;
}

.galleryItem {
  position: relative;
  overflow: hidden;
}

.galleryItem::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(
    0deg,
    color-mix(in srgb, var(--vt-surface-deep) 50%, transparent) 0%,
    transparent 50%
  );
  opacity: 0;
  transition: opacity 0.4s ease;
}

.galleryItem:hover::after {
  opacity: 1;
}

.galleryItem img {
  transition: transform 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.galleryItem:hover img {
  transform: scale(1.04);
}

.galleryCaption {
  position: absolute;
  bottom: 1rem;
  left: 1rem;
  right: 1rem;
  z-index: 2;
  color: var(--vt-on-deep);
  opacity: 0;
  transform: translateY(8px);
  transition: opacity 0.4s ease 0.05s, transform 0.4s ease 0.05s;
}

.galleryItem:hover .galleryCaption {
  opacity: 1;
  transform: translateY(0);
}

.galleryCaptionTitle {
  font-family: 'Playfair Display', Georgia, serif;
  font-size: 1rem;
  font-weight: 500;
  margin-bottom: 0.2rem;
}

.galleryCaptionSub {
  font-family: 'Inter', system-ui, sans-serif;
  font-size: 0.7rem;
  font-weight: 400;
  letter-spacing: 0.04em;
  opacity: 0.7;
}

.tall {
  grid-row: span 2;
}

/* Contact */
.contact {
  padding: var(--space-xl) var(--gutter);
  background: var(--vt-surface-2);
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--gutter);
  align-items: center;
}

.findUsWrapper {
  max-width: 100%;
  overflow: hidden;
  /* Fix mechanical overflow: ensure map fits inside container */
  width: 100%;
}

.contactInfo {
  padding: 0 var(--space-sm);
}

.contactTitle {
  font-family: 'Playfair Display', Georgia, serif;
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 400;
  line-height: 1.15;
  letter-spacing: -0.02em;
  margin-bottom: 1.5rem;
  color: var(--vt-ink);
}

.contactPhone {
  font-family: 'Inter', system-ui, sans-serif;
  font-size: 1.1rem;
  margin-bottom: 0.5rem;
}

.contactPhone a {
  color: var(--vt-accent);
  text-decoration: none;
}

.contactHours,
.contactAreas {
  font-family: 'Inter', system-ui, sans-serif;
  font-size: 0.9rem;
  color: var(--vt-ink-soft);
  margin-bottom: 0.75rem;
}

/* Footer */
.siteFooter {
  padding: var(--space-xl) var(--gutter) var(--space-md);
  background: var(--vt-surface-deep);
  color: var(--vt-on-deep);
}

.footerTop {
  display: grid;
  grid-template-columns: 1.5fr repeat(2, 1fr);
  gap: var(--gutter);
  padding-bottom: var(--space-lg);
  border-bottom: 1px solid color-mix(in srgb, var(--vt-on-deep) 10%, transparent);
}

.footerBrand {
  /* */
}

.footerBrandLogo {
  display: block;
  margin-bottom: 1.5rem;
  color: var(--vt-on-deep);
}

.footerBrandDesc {
  font-family: 'Inter', system-ui, sans-serif;
  font-size: 0.85rem;
  line-height: 1.7;
  color: color-mix(in srgb, var(--vt-on-deep) 50%, transparent);
  max-width: 32ch;
}

.footerColTitle {
  font-family: 'Inter', system-ui, sans-serif;
  font-size: 0.65rem;
  font-weight: 600;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: color-mix(in srgb, var(--vt-on-deep) 35%, transparent);
  margin-bottom: 1.5rem;
}

.footerCol ul {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.footerCol a {
  font-family: 'Inter', system-ui, sans-serif;
  font-size: 0.85rem;
  font-weight: 400;
  color: color-mix(in srgb, var(--vt-on-deep) 70%, transparent);
  transition: color 0.3s ease;
}

.footerCol a:hover {
  color: var(--vt-on-deep);
  opacity: 1;
}

.footerSocialLinks {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.footerSocialLinks a {
  font-family: 'Inter', system-ui, sans-serif;
  font-size: 0.85rem;
  font-weight: 400;
  color: color-mix(in srgb, var(--vt-on-deep) 70%, transparent);
  transition: color 0.3s ease;
}

.footerSocialLinks a:hover {
  color: var(--vt-on-deep);
  opacity: 1;
}

.footerBottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: var(--space-md);
}

.footerCopy {
  font-family: 'Inter', system-ui, sans-serif;
  font-size: 0.75rem;
  color: color-mix(in srgb, var(--vt-on-deep) 30%, transparent);
}

.footerCopy a {
  color: color-mix(in srgb, var(--vt-on-deep) 50%, transparent);
}

/* Responsive */
@media (max-width: 1024px) {
  .routeChapters {
    padding: var(--space-md) var(--gutter);
  }

  .chapter {
    min-height: auto;
    padding: 6vh 0;
  }

  .galleryGrid {
    grid-template-columns: repeat(2, 1fr);
  }

  .footerTop {
    grid-template-columns: 1fr 1fr;
    row-gap: var(--space-md);
  }

  .contact {
    grid-template-columns: 1fr;
    gap: var(--space-md);
  }
}

@media (max-width: 680px) {
  .navLinks {
    display: none;
  }

  .heroTitle {
    font-size: clamp(2.5rem, 12vw, 4.5rem);
  }

  .heroScroll {
    display: none;
  }

  .heroMeta {
    flex-wrap: wrap;
    gap: 1rem;
  }

  .prologueText::first-letter {
    font-size: 4em;
  }

  .chapterNumber {
    font-size: 3.5rem;
  }

  .galleryGrid {
    grid-template-columns: 1fr 1fr;
    grid-auto-rows: clamp(140px, 30vw, 200px);
  }

  .footerTop {
    grid-template-columns: 1fr;
  }

  .footerBottom {
    flex-direction: column;
    gap: 1.5rem;
    text-align: center;
  }
}

@media (prefers-reduced-motion: reduce) {
  .heroScroll::before {
    animation: none;
  }

  .galleryItem img {
    transition: none;
  }
}
